// Vitrine et riverains : statuts de logements visibles, données privées servies par /cercle-demo/.
const occupiedHomes=[{id:'home-1',name:'Maison riveraine M01',x:-159,y:-130,containers:'C01 · C02'},{id:'home-2',name:'Maison riveraine M02',x:-81,y:-130,containers:'C03 · C04'},{id:'home-3',name:'Maison riveraine M03',x:-159,y:-68,containers:'C05 · C06'}];
stayCatalog.find(p=>p.id==='luxe').units=1;stayCatalog.find(p=>p.id==='container').units=2;
for(const h of occupiedHomes)cityPlaces.push({id:h.id,name:h.name,short:h.name,icon:'⌂',label:h.name.toUpperCase(),x:h.x,y:h.y,occupancy:'resident',containers:h.containers,desc:'Maison du scénario riverain, occupée à l’année et exclue des réservations publiques.',stat:'2',unit:'containers',stat2:'Privé',unit2:'espace riverain',action:'Comprendre l’espace riverains',route:'riverains'});
cityPlaces.push({id:'home-4',name:'Les suites containers C07 & C08',short:'2 suites containers à louer',icon:'⌂',label:'SUITES À LOUER',x:-81,y:-68,occupancy:'rental',stay:'container',desc:'Deux suites indépendantes dans le scénario locatif.',stat:'2',unit:'containers à louer',stat2:'Séjour',unit2:'scénario locatif',action:'Choisir un séjour',route:'sejours'});
for(const id of ['habitats','stay-container']){const h=cityPlaces.find(p=>p.id===id);if(h){h.hiddenFromList=true;delete h.stay}}
const domainPlace=cityPlaces.find(p=>p.id==='domaine');domainPlace.occupancy='rental';domainPlace.short='Maison en L à louer';domainPlace.label='MAISON EN L · À LOUER';
for(const h of cityPlaces.filter(p=>p.stay&&!p.occupancy))h.occupancy='rental';
function estateVisiblePlace(p){if(p.hiddenFromList)return false;if(estateMapMode==='riverains')return p.occupancy==='resident';if(estateMapMode==='sejours')return p.occupancy==='rental';if(estateMapMode==='services')return !p.occupancy;return true}
function estateVisibleLabel(p,width){if(!estateVisiblePlace(p)&&p.id!==citySelected)return false;if(p.hiddenFromList)return false;if(p.id===citySelected)return true;if(estateMapMode==='riverains'||estateMapMode==='sejours')return width>=480||['home-1','home-4','domaine'].includes(p.id);return width>=600?['home-1','home-4','domaine','parking','casiers','jardins','marche'].includes(p.id):['home-1','domaine','parking'].includes(p.id)}
estateMapFilter=function(mode){estateMapMode=mode;citySelected=mode==='riverains'?'home-1':mode==='sejours'?'domaine':'parking';render()};
const cityDetailBeforeSpaces=cityDetailHTML;cityDetailHTML=function(){const p=cityPlaces.find(p=>p.id===citySelected);if(p?.occupancy==='resident')return `<div class="occupancy-badge resident">MAISON RIVERAINE · SCÉNARIO</div><div class="estate-place-art">${domainPlan()}</div><h2>${p.name}</h2><p>Deux containers (${p.containers}) composent cette maison réservée à la vie des riverains. Elle n’est pas proposée à la location.</p><div class="private-map-info"><b>Accès riverains authentifié</b><p>Discussions internes, décisions et relevés du logement sont réservés aux comptes autorisés.</p><a class="btn" href="/cercle-demo/">Accéder à l’espace privé ↗</a></div><p class="smallnote">Occupation projetée pour la présentation. Aucun nom d’habitant, code Wi-Fi ou relevé privé n’est affiché sur ce plan public.</p>`;let html=cityDetailBeforeSpaces();if(p?.occupancy==='rental')html='<div class="occupancy-badge rental">À LOUER · SÉJOUR DE DÉMONSTRATION</div>'+html;return html};
const cityActionBeforeSpaces=cityAction;cityAction=function(id){const p=cityPlaces.find(p=>p.id===id);if(p?.occupancy==='resident'){location.href='/cercle-demo/';return}cityActionBeforeSpaces(id)};
const cityViewBeforeSpaces=views.ville;views.ville=function(){return `<section class="spaces-legend"><div><i class="resident-dot"></i><b>Riverains</b><span>3 maisons en L · 6 containers · non réservables</span></div><div><i class="rental-dot"></i><b>Location</b><span>2 suites + 1 maison en L · 4 containers</span></div><small>Répartition de démonstration · laboratoire hors total des 10 containers.</small></section>`+cityViewBeforeSpaces()};
const cardsBeforeSpaces=stayCards;stayCards=function(items){return cardsBeforeSpaces(items).replaceAll('par nuit fictive','par nuit fictive').replaceAll('<div class="stay-body"><small>','<div class="stay-body"><span class="occupancy-badge rental">À louer · scénario</span><small>')};
function publicResidentGate(){return `<section class="resident-public-gate"><img src="assets/maison-l-bois-reference.webp" alt="Visualisation d’une maison riveraine du Domaine"><div><div class="eyebrow">DEUX ESPACES · DEUX USAGES</div><h1>Visiter librement.<br>Vivre en privé.</h1><p>La vitrine permet de découvrir le Domaine et les hébergements à louer. Les échanges internes et les relevés des logements appartiennent à l’espace riverains authentifié.</p><div class="spaces-gate-actions"><a class="btn" href="/cercle-demo/">Explorer l’application ↗</a><a class="btn light" href="#sejours">Découvrir les locations ↗</a></div><p class="smallnote">L’accès privé nécessite une connexion compte riverain et une autorisation du gestionnaire. Aucune donnée privée n’est stockée dans la vitrine publique.</p></div></section>`}
views.riverains=publicResidentGate;views.resident=publicResidentGate;routes.push(['riverains','⌂','Espace privé riverains']);routes.find(r=>r[0]==='resident')[2]='Accès riverains';
let circlePublicDemo=false;
const localCircleDemo=views.communaute;views.communaute=function(){if(circlePublicDemo)return `<div class="private-demo-bar"><span>Vous explorez une démonstration locale du Cercle, sans lien avec la base privée.</span><a href="/cercle-demo/">Entrer dans l’application ↗</a><button onclick="circlePublicDemo=false;render()">Quitter la démo</button></div>`+localCircleDemo();return `<section class="circle-hero"><img src="assets/jardin-photo.webp" alt="Visualisation des jardins et de la vie commune"><div><div class="eyebrow">LE CŒUR DU DOMAINE</div><h1>La vie commune<br>se construit ensemble.</h1><p>Décisions, activités, entraide et conversations.<br>Un réseau réservé aux riverains autorisés.</p><div class="circle-hero-actions"><a class="btn" href="/cercle-demo/">Rejoindre l’espace privé ↗</a><button class="btn light" onclick="circlePublicDemo=true;render()">Essayer la démonstration locale</button></div></div></section><div class="circle-public-points">${[['01','Échanger en confiance','Les publications internes sont accessibles uniquement aux comptes autorisés.'],['02','Décider ensemble','Des propositions, un choix par compte, des résultats et une clôture du vote.'],['03','Se rencontrer','Créer des activités et partager les inscriptions entre les membres.'],['04','Respecter chaque logement','Chaque riverain accède aux relevés de son habitat. Le gestionnaire autorise les comptes.']].map(x=>`<article class="panel"><span class="eyebrow">${x[0]}</span><h2>${x[1]}</h2><p>${x[2]}</p></article>`).join('')}</div><div class="travel-demo">La base privée démarre sans faux messages ni faux habitants. Le propriétaire est gestionnaire ; il pourra autoriser les futurs riverains.</div>`};
const homeBeforeSpaces=views.accueil;views.accueil=function(){return homeBeforeSpaces().replace('<div class="welcome-shortcuts">','<div class="spaces-entry"><a href="#sejours"><span>SÉJOURNER AU DOMAINE</span><b>Je cherche un hébergement ↗</b></a><a href="/cercle-demo/"><span>ESPACE PRIVÉ</span><b>Je suis riverain ↗</b></a></div><div class="welcome-shortcuts">')};
const renderBeforeSpaces=render;render=function(){renderBeforeSpaces();const nav=$('#nav');nav.querySelectorAll('a[href="#resident"]').forEach(a=>a.remove());let privateLink=nav.querySelector('a[href="#riverains"]');if(privateLink){privateLink.href='/cercle-demo/';privateLink.textContent='⌂ Espace privé riverains'}let top=document.querySelector('.headerend .private-header-link');if(!top){top=document.createElement('a');top.href='/cercle-demo/';top.className='private-header-link';top.textContent='L’application';document.querySelector('.headerend').prepend(top)}};
slides.splice(1,0,{k:'PUBLIC & RIVERAINS',title:'Accueillir des visiteurs.<br>Préserver la vie des habitants.',text:'Le Domaine distingue ses logements riverains et ses hébergements à louer, avec un espace privé séparé de la présentation publique.',cards:[['Trois maisons riveraines','Six containers réservés à la vie résidentielle. Ils ne sont pas proposés à la location.'],['Un espace de séjour','Deux suites containers et une maison en L dans le scénario locatif.'],['Un accès authentifié','Connexion puis autorisation du gestionnaire. Données privées contrôlées côté serveur.']]});slides.forEach((s,i)=>s.k=String(i+1).padStart(2,'0')+' · '+s.k.replace(/^\d+ · /,''));
render();
